ORBE = dict(nombre="ASISTENTE APEX", color="#7fd8f0", voz=("es-CO-SalomeNeural", "+4%", "+2Hz"), fx="radio")
def N(txt, pausa=0.4): return ("narrador", txt, pausa, {})
def O(txt, pausa=0.4): return ("orbe", txt, pausa, {})
